/**
 * 极简 vitest 兼容层
 *
 * 容器内没有网络，装不了真正的 vitest。这里实现测试文件实际用到的那部分 API，
 * 让作者自带的 10 个测试文件能原样跑起来，用来验证合并后的代码没被改坏。
 *
 * 不追求完整实现，只覆盖 tests/ 目录里出现过的断言和 mock 能力。
 */

import assert from 'node:assert/strict';
import util from 'node:util';

const suites = [];
let currentSuite = null;

export function describe(name, fn) {
    const parent = currentSuite;
    const suite = { name, tests: [], beforeEach: [], afterEach: [], children: [], parent };
    if (parent) parent.children.push(suite);
    else suites.push(suite);
    currentSuite = suite;
    fn();
    currentSuite = parent;
}

export function it(name, optionsOrFn, maybeFn) {
    if (!currentSuite) throw new Error('it() 必须在 describe() 内');
    // 支持 it(name, fn) 与 it(name, { timeout }, fn) 两种写法
    const fn = typeof optionsOrFn === 'function' ? optionsOrFn : maybeFn;
    const options = typeof optionsOrFn === 'object' && optionsOrFn ? optionsOrFn : {};
    currentSuite.tests.push({ name, fn, options });
}
it.skip = () => {};
describe.skip = () => {};

export function beforeEach(fn) {
    if (currentSuite) currentSuite.beforeEach.push(fn);
}
export function afterEach(fn) {
    if (currentSuite) currentSuite.afterEach.push(fn);
}
export function beforeAll(fn) {
    if (currentSuite) currentSuite.beforeEach.push(fn);
}
export function afterAll(fn) {
    if (currentSuite) currentSuite.afterEach.push(fn);
}

// ===== fake timers =====
const realSetTimeout = globalThis.setTimeout;
const realClearTimeout = globalThis.clearTimeout;
const realSetInterval = globalThis.setInterval;
const realClearInterval = globalThis.clearInterval;
let fakeTimers = null;

function installFakeTimers() {
    fakeTimers = { queue: [], now: 0, nextId: 1 };
    globalThis.setTimeout = (fn, delay = 0, ...args) => {
        const id = fakeTimers.nextId++;
        fakeTimers.queue.push({ id, fn, time: fakeTimers.now + delay, args, interval: null });
        return id;
    };
    globalThis.clearTimeout = (id) => {
        if (!fakeTimers) return;
        fakeTimers.queue = fakeTimers.queue.filter((t) => t.id !== id);
    };
    globalThis.setInterval = (fn, delay = 0, ...args) => {
        const id = fakeTimers.nextId++;
        fakeTimers.queue.push({ id, fn, time: fakeTimers.now + delay, args, interval: delay });
        return id;
    };
    globalThis.clearInterval = globalThis.clearTimeout;
}

function uninstallFakeTimers() {
    globalThis.setTimeout = realSetTimeout;
    globalThis.clearTimeout = realClearTimeout;
    globalThis.setInterval = realSetInterval;
    globalThis.clearInterval = realClearInterval;
    fakeTimers = null;
}

/** 让出若干轮事件循环，等待被测代码把下一个定时器排进队列 */
async function drainMicrotasks(rounds = 12) {
    for (let i = 0; i < rounds; i++) {
        await new Promise((r) => realSetTimeout(r, 0));
    }
}

async function runAllTimersAsync(limit = 10000) {
    if (!fakeTimers) return;
    let guard = 0;
    const deadline = Date.now() + 20000; // 兜底，防止死循环卡住整个测试进程

    while (guard++ < limit && Date.now() < deadline) {
        if (fakeTimers.queue.length === 0) {
            // 队列暂时空了，但被测代码可能正处于 await 链中间、
            // 马上就要排下一个定时器。多让几轮再确认。
            await drainMicrotasks();
            if (!fakeTimers || fakeTimers.queue.length === 0) break;
        }

        fakeTimers.queue.sort((a, b) => a.time - b.time);
        const timer = fakeTimers.queue.shift();
        fakeTimers.now = Math.max(fakeTimers.now, timer.time);
        try {
            await timer.fn(...timer.args);
        } catch (e) {
            // 定时器回调里的异常由被测代码自己的 promise 链处理
        }
        await drainMicrotasks(3);
    }
}

// ===== vi =====
export const vi = {
    fn(impl) {
        const calls = [];
        const results = [];
        const onceQueue = [];
        let implementation = impl;
        const mockFn = (...args) => {
            calls.push(args);
            // once 队列优先，模拟 mockResolvedValueOnce / mockRejectedValueOnce
            const once = onceQueue.shift();
            const active = once || implementation;
            if (typeof active === 'function') {
                const out = active(...args);
                results.push(out);
                return out;
            }
            results.push(undefined);
            return undefined;
        };
        mockFn.mock = { calls, results };
        mockFn.mockReturnValue = (v) => {
            implementation = () => v;
            return mockFn;
        };
        mockFn.mockResolvedValue = (v) => {
            implementation = () => Promise.resolve(v);
            return mockFn;
        };
        mockFn.mockRejectedValue = (v) => {
            implementation = () => Promise.reject(v);
            return mockFn;
        };
        mockFn.mockImplementation = (f) => {
            implementation = f;
            return mockFn;
        };
        mockFn.mockReturnValueOnce = (v) => {
            onceQueue.push(() => v);
            return mockFn;
        };
        mockFn.mockResolvedValueOnce = (v) => {
            onceQueue.push(() => Promise.resolve(v));
            return mockFn;
        };
        mockFn.mockRejectedValueOnce = (v) => {
            onceQueue.push(() => Promise.reject(v));
            return mockFn;
        };
        mockFn.mockImplementationOnce = (f) => {
            onceQueue.push(f);
            return mockFn;
        };
        mockFn.mockClear = () => {
            calls.length = 0;
            results.length = 0;
            return mockFn;
        };
        mockFn.mockReset = mockFn.mockClear;
        mockFn.__isMockFunction = true;
        return mockFn;
    },
    useFakeTimers: installFakeTimers,
    useRealTimers: uninstallFakeTimers,
    runAllTimersAsync,
    advanceTimersByTime: runAllTimersAsync,
    clearAllMocks() {},
    resetAllMocks() {},
    spyOn(obj, key) {
        const original = obj[key];
        const spy = vi.fn((...args) => original.apply(obj, args));
        spy.mockRestore = () => {
            obj[key] = original;
        };
        obj[key] = spy;
        return spy;
    },
};

// ===== expect =====
function fmt(v) {
    return util.inspect(v, { depth: 3, breakLength: 100 });
}

class Expectation {
    constructor(actual, negated = false) {
        this.actual = actual;
        this.negated = negated;
    }
    get not() {
        return new Expectation(this.actual, !this.negated);
    }
    _check(pass, message) {
        const ok = this.negated ? !pass : pass;
        if (!ok) throw new assert.AssertionError({ message: (this.negated ? '[not] ' : '') + message });
    }
    toBe(expected) {
        this._check(Object.is(this.actual, expected), `期望 ${fmt(expected)}，实际 ${fmt(this.actual)}`);
    }
    toEqual(expected) {
        let pass = true;
        try {
            assert.deepStrictEqual(this.actual, expected);
        } catch {
            pass = false;
        }
        this._check(pass, `深比较失败\n期望: ${fmt(expected)}\n实际: ${fmt(this.actual)}`);
    }
    toStrictEqual(expected) {
        this.toEqual(expected);
    }
    toContain(needle) {
        const a = this.actual;
        const pass = Array.isArray(a) ? a.includes(needle) : String(a).includes(needle);
        this._check(pass, `${fmt(this.actual)} 不包含 ${fmt(needle)}`);
    }
    toHaveLength(n) {
        this._check(this.actual != null && this.actual.length === n, `期望长度 ${n}，实际 ${this.actual?.length}`);
    }
    toBeUndefined() {
        this._check(this.actual === undefined, `期望 undefined，实际 ${fmt(this.actual)}`);
    }
    toBeDefined() {
        this._check(this.actual !== undefined, `期望有定义，实际 undefined`);
    }
    toBeNull() {
        this._check(this.actual === null, `期望 null，实际 ${fmt(this.actual)}`);
    }
    toBeTruthy() {
        this._check(!!this.actual, `期望真值，实际 ${fmt(this.actual)}`);
    }
    toBeFalsy() {
        this._check(!this.actual, `期望假值，实际 ${fmt(this.actual)}`);
    }
    toBeGreaterThan(n) {
        this._check(this.actual > n, `期望 > ${n}，实际 ${fmt(this.actual)}`);
    }
    toBeGreaterThanOrEqual(n) {
        this._check(this.actual >= n, `期望 >= ${n}，实际 ${fmt(this.actual)}`);
    }
    toBeLessThan(n) {
        this._check(this.actual < n, `期望 < ${n}，实际 ${fmt(this.actual)}`);
    }
    toBeLessThanOrEqual(n) {
        this._check(this.actual <= n, `期望 <= ${n}，实际 ${fmt(this.actual)}`);
    }
    toBeInstanceOf(cls) {
        this._check(this.actual instanceof cls, `期望是 ${cls.name} 实例，实际 ${fmt(this.actual)}`);
    }
    toThrow(expected) {
        if (this.negated) {
            let threw = false;
            let msg = '';
            try {
                this.actual();
            } catch (e) {
                threw = true;
                msg = String(e && e.message);
            }
            if (threw) {
                throw new assert.AssertionError({ message: `期望不抛错，实际抛出 "${msg}"` });
            }
            return;
        }
        let threw = false;
        let err = null;
        try {
            this.actual();
        } catch (e) {
            threw = true;
            err = e;
        }
        if (expected === undefined) {
            this._check(threw, '期望抛错，但没有抛出');
        } else {
            const msg = err ? String(err.message) : '';
            const pass = threw && (expected instanceof RegExp ? expected.test(msg) : msg.includes(expected));
            this._check(pass, `期望抛出含 ${fmt(expected)} 的错误，实际 ${threw ? msg : '没抛错'}`);
        }
    }
    toHaveBeenCalled() {
        this._check(this.actual.mock.calls.length > 0, '期望被调用过，实际没有');
    }
    toHaveBeenCalledOnce() {
        this._check(this.actual.mock.calls.length === 1, `期望调用 1 次，实际 ${this.actual.mock.calls.length} 次`);
    }
    toHaveBeenCalledTimes(n) {
        this._check(this.actual.mock.calls.length === n, `期望调用 ${n} 次，实际 ${this.actual.mock.calls.length} 次`);
    }
    toHaveBeenCalledWith(...args) {
        const pass = this.actual.mock.calls.some((call) => {
            try {
                assert.deepStrictEqual(call, args);
                return true;
            } catch {
                return false;
            }
        });
        this._check(pass, `没有以 ${fmt(args)} 调用过，实际调用记录 ${fmt(this.actual.mock.calls)}`);
    }
    /**
     * expect(promise).rejects.toThrow(...) —— 返回一个断言代理，
     * 其方法返回 Promise，供 await 使用。
     */
    get rejects() {
        const actual = this.actual;
        const negated = this.negated;
        return {
            async toThrow(expected) {
                let threw = false;
                let err = null;
                try {
                    await (typeof actual === 'function' ? actual() : actual);
                } catch (e) {
                    threw = true;
                    err = e;
                }
                const msg = err ? String(err.message) : '';
                let pass;
                if (expected === undefined) {
                    pass = threw;
                } else {
                    pass =
                        threw &&
                        (expected instanceof RegExp ? expected.test(msg) : msg.includes(String(expected)));
                }
                if (negated ? pass : !pass) {
                    throw new assert.AssertionError({
                        message: `期望 Promise 被拒绝${expected !== undefined ? `且错误含 ${fmt(expected)}` : ''}，实际 ${threw ? `错误是 "${msg}"` : '正常完成'}`,
                    });
                }
            },
            async toThrowError(expected) {
                return this.toThrow(expected);
            },
            async toBe(expected) {
                let err = null;
                try {
                    await (typeof actual === 'function' ? actual() : actual);
                } catch (e) {
                    err = e;
                }
                if (!Object.is(err, expected)) {
                    throw new assert.AssertionError({ message: `期望拒绝值 ${fmt(expected)}，实际 ${fmt(err)}` });
                }
            },
        };
    }

    get resolves() {
        const actual = this.actual;
        return {
            async toBe(expected) {
                const v = await (typeof actual === 'function' ? actual() : actual);
                if (!Object.is(v, expected)) {
                    throw new assert.AssertionError({ message: `期望解析为 ${fmt(expected)}，实际 ${fmt(v)}` });
                }
            },
            async toEqual(expected) {
                const v = await (typeof actual === 'function' ? actual() : actual);
                assert.deepStrictEqual(v, expected);
            },
        };
    }
}

export function expect(actual) {
    return new Expectation(actual);
}
expect.any = (cls) => ({ __any: cls });

// ===== runner =====
async function runSuite(suite, prefix, stats, ancestors = []) {
    const chain = [...ancestors, suite];
    for (const test of suite.tests) {
        const label = `${prefix}${suite.name} › ${test.name}`;
        try {
            for (const s of chain) for (const hook of s.beforeEach) await hook();
            await test.fn();
            for (const s of [...chain].reverse()) for (const hook of s.afterEach) await hook();
            stats.pass++;
        } catch (e) {
            stats.fail++;
            stats.failures.push({ label, error: e });
            try {
                for (const s of [...chain].reverse()) for (const hook of s.afterEach) await hook();
            } catch {
                /* 清理失败不影响主流程 */
            }
        }
    }
    for (const child of suite.children) {
        await runSuite(child, prefix, stats, chain);
    }
}

export async function __runAll(fileLabel) {
    const stats = { pass: 0, fail: 0, failures: [] };
    for (const suite of suites) {
        await runSuite(suite, '', stats);
    }
    suites.length = 0;
    return { fileLabel, ...stats };
}

export default { describe, it, expect, vi, beforeEach, afterEach };
